def apply(text, pairs, name):
    missing = []
    for a, b in pairs:
        if a not in text: missing.append(a[:70]); continue
        text = text.replace(a, b)
    if missing:
        print(f'[{name}] textos no encontrados (actualizá _tools/build_en.py):'); [print('  -', m) for m in missing]; sys.exit(1)
    return text

html = apply((ROOT / 'index.html').read_text(), HTML, 'index.html')
html = re.sub(r'href="#([\w-]+)"', r'href="en/#\1"', html)            # anclas con <base href="../">
html = html.replace('<textPath href="en/#circ">', '<textPath href="#circ">')
html = re.sub(r'src="app\.js(\?v=\d+)?"', lambda m: f'src="en/app.js{m.group(1) or ""}"', html)
# el ¿Conocías…? dentro del celular es la app real (en español); las opciones del simulador se traducen
html = html.replace('<button type="button" class="on">Sí</button><button type="button">Poco</button><button type="button">No</button>',
                    '<button type="button" class="on">Yes</button><button type="button">A little</button><button type="button">No</button>')
html = html.replace('<p class="sv-q">¿Conocías Tu Marca?</p>', '<p class="sv-q">Did you know Your Brand?</p>')
html = html.replace('<b>¡Aplicaste el beneficio con éxito!</b><small>Contanos cómo fue tu experiencia</small>', '<b>Perk redeemed successfully!</b><small>Tell us about your experience</small>')
html = html.replace('<p class="sv-q">¿Cómo valorarías su atención?</p>', '<p class="sv-q">How would you rate the service?</p>')
html = html.replace('<p class="sv-q">¿Qué podríamos mejorar?</p>', '<p class="sv-q">What could we improve?</p>')
html = html.replace('<div class="sv-text">Me encantaría encontrar más talles…<i></i></div>', '<div class="sv-text">I’d love to find more sizes…<i></i></div>')
html = html.replace('<span class="sv-send">Enviar respuesta</span>', '<span class="sv-send">Send response</span>')
leftover = [w for w in ['Mirá', 'Elegí', 'Tocá', 'Respetá', 'Conocé', 'Destacá', 'Activá', 'shoppings de', ' tu marca', 'Medidas'] if w in re.sub(r'<script.*?</script>', '', html, flags=re.S)]
if leftover: print('Aviso: posibles textos sin traducir en HTML:', leftover)
js = apply((ROOT / 'app.js').read_text(), JS, 'app.js')
(ROOT / 'en').mkdir(exist_ok=True)
(ROOT / 'en' / 'index.html').write_text(html)
(ROOT / 'en' / 'app.js').write_text(js)
print('OK: en/index.html y en/app.js generados')
